def transform(grid):
    """Fill each fully enclosed background region by its area parity."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 9 and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 9 and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 9 and not seen[nr][nc]:
                seen[nr][nc] = True
                q.append((nr, nc))
    # Any background component not connected to the edge is inside an outline.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 9 or seen[r][c]:
                continue
            comp = []
            seen[r][c] = True
            q.append((r, c))
            while q:
                cr, cc = q.popleft()
                comp.append((cr, cc))
                for nr, nc in ((cr-1,cc), (cr+1,cc), (cr,cc-1), (cr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 9 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            fill = 2 if len(comp) % 2 == 0 else 7
            for cr, cc in comp:
                out[cr][cc] = fill
    return out
